def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    skiers_patches = image_patch.find("skier")
    if not skiers_patches:
        return image_patch

    # Find the topmost skier
    top_skier = min(skiers_patches, key=lambda p: p.upper)

    # Find the railing behind the skiers
    railing_patches = image_patch.find("railing")
    if not railing_patches:
        return top_skier

    # Filter railings to find the topmost one behind the skiers
    behind_skiers = [r for r in railing_patches if r.upper < top_skier.upper]
    if not behind_skiers:
        return top_skier

    # Find the topmost blue railing
    blue_railings = [r for r in behind_skiers if r.verify_property("railing", "blue")]
    if not blue_railings:
        return behind_skiers[0]

    return min(blue_railings, key=lambda r: r.upper)

