def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    ski_rack_patches = image_patch.find("ski rack")
    if not ski_rack_patches:
        return image_patch

    # Filter for blue ski racks
    blue_ski_racks = [rack for rack in ski_rack_patches if image_patch.verify_property(rack, "blue")]
    if not blue_ski_racks:
        return ski_rack_patches[0]

    # Find the child in front of the blue ski rack
    child_patches = image_patch.find("child")
    if not child_patches:
        return blue_ski_racks[0]

    # Sort child patches by depth
    child_patches.sort(key=lambda c: c.compute_depth())

    # Find the child in front of the first blue ski rack
    for child in child_patches:
        if any(distance(child, rack) < 0 for rack in blue_ski_racks):
            return child

    return blue_ski_racks[0]

